class Sensor:
    def __init__(self, name, value):
        self.name = name
        self.value = value


class Station:
    def __init__(self, name):
        self.name = name
        self.sensors = []

    def add(self, sensor):
        self.sensors.append(sensor)
        return sensor

    def summary(self):
        if not self.sensors:
            return f"{self.name}: no sensors"
        parts = [f"{s.name}={s.value}" for s in self.sensors]
        return f"{self.name}: " + ", ".join(parts)


station = Station("Ridge")
station.add(Sensor("soil", 11))
station.add(Sensor("wind", 18))

print(station.summary())
